<script>
function editDocument(encoded){var item=JSON.parse(atob(encoded)),form=document.getElementById('documentForm');form.action=@json(route('organization.update',['document-types','__ID__'])).replace('__ID__',item.id);document.getElementById('documentMethod').innerHTML='<input type="hidden" name="_method" value="PUT">';form.elements.name.value=item.name||'';form.elements.description.value=item.description||'';form.elements.is_required.value=Number(item.is_required)?'1':'0';document.getElementById('documentFormTitle').textContent='Edit Document Type';document.getElementById('documentFormHelp').textContent='Update the document type details';document.getElementById('documentSubmit').textContent='Update Document Type';document.getElementById('documentCancel').style.display='';form.scrollIntoView({behavior:'smooth',block:'start'})}
function resetDocumentForm(){var form=document.getElementById('documentForm');form.reset();form.action=@json(route('organization.store','document-types'));document.getElementById('documentMethod').innerHTML='';document.getElementById('documentFormTitle').textContent='Add New Document Type';document.getElementById('documentFormHelp').textContent='Fill in the details to create a new document type';document.getElementById('documentSubmit').textContent='Add Document Type';document.getElementById('documentCancel').style.display='none'}
function toggleDocumentDescription(button){var description=button.previousElementSibling,open=!description.classList.contains('collapsed');description.classList.toggle('collapsed');button.textContent=open?'⌄ Show more':'⌃ Show less'}
document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.document-confirm').forEach(function(form){form.addEventListener('submit',function(event){if(form.dataset.confirmed)return;event.preventDefault();Swal.fire({title:'Delete this document type permanently?',icon:'warning',showCancelButton:true,confirmButtonColor:'#00b783'}).then(function(result){if(result.isConfirmed){form.dataset.confirmed='1';form.submit()}})})});@if($errors->any())document.getElementById('documentForm').scrollIntoView();@endif});
</script>
